{
  "headline": "FDA's records trace our supply to a plant classified VAI 693 days before the shortage posting",
  "headline_cites": ["D4"],
  "sentences": [
    {
      "text": "FDA inspection 1110628 of Gland Pharma Limited ended on 2019-11-01 and was classified VAI, with the classification letter dated 2019-12-10.",
      "cites": ["E10"]
    },
    {
      "text": "That inspection occurred 693 days before FDA posted the cytarabine shortage on 2021-09-24.",
      "cites": ["D4"]
    },
    {
      "text": "As of 2026-10-21 the shortage has been on FDA's list for 61 months.",
      "cites": ["D8"]
    },
    {
      "text": "A label for cytarabine 20 mg/mL names Gland Pharma Limited as the manufacturing plant (FEI 3009056604).",
      "cites": ["E11"]
    },
    {
      "text": "The rule-based best option is to buy from Meitheal Pharmaceuticals Inc., which is not on FDA's shortage list today and uses Kindos Pharmaceuticals Co., Ltd. (last inspection VAI 2024-07-19).",
      "cites": ["D5"]
    },
    {
      "text": "An alternate manufacturer option is the same product from Gland Pharma Limited (NDC 68083034305), approved for P&T interchange on 2026-01-15.",
      "cites": ["D6", "E12"]
    },
    {
      "text": "Current on-hand supply across Corvale sites ranges from 12 to 23 days at present usage rates.",
      "cites": ["D1", "D2", "D3"]
    }
  ]
}
